283					t.Errorf("No route facts %v, want the raw text %q", noRoute, tc.noRouteFactIn)
284				}
285				if tc.undetFactIn != "" && !strings.Contains(strings.Join(undet, "|"), tc.undetFactIn) {
286					t.Errorf("Route undetermined facts %v, want the raw text %q", undet, tc.undetFactIn)
287				}
288			})
289		}
290	}
291	
292	// TestTheRouteStageGatesNothing keeps a machine whose routing table cannot be
293	// read from losing every check below it. The reach stage makes the same
294	// promise for the same reason.
295	func TestTheRouteStageGatesNothing(t *testing.T) {
296		for _, s := range stages() {
297			if s.id == StageRoute && s.gate != "" {
298				t.Fatalf("the route stage gates %q — a routing table that cannot be read "+
299					"must not cascade over the port and the certificate", s.gate)
300			}
301		}
302	}
