1	package netcheck
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net"
8		"strings"
9		"syscall"
10		"testing"
11	
12		"github.com/anthnel/devdesk/internal/nettrace"
13	)
14	
15	// routeCheck runs the route stage against prior and returns its one check.
16	func routeCheck(t *testing.T, env Env, tg Target, prior Results) Check {
17		t.Helper()
18		checks := runRoute(context.Background(), tg, env, DefaultSettings(), &prior)
19		if len(checks) != 1 {
20			t.Fatalf("route stage produced %d checks, want 1", len(checks))
21		}
22		return checks[0]
23	}
24	
25	// resolvedTo builds the prior Results a resolve stage would have left behind.
26	func resolvedTo(t *testing.T, ips ...net.IP) Results {
27		t.Helper()
28		env := fakeEnv{resolve: func(context.Context, string, string) ([]net.IP, error) { return ips, nil }}
29		var prior Results
30		return ResultsOf(runResolve(context.Background(), target(), env, DefaultSettings(), &prior)...)
31	}
32	
33	// TestTheRouteStageReadsWhatTheResolveStageWrote pins the coupling this stage
34	// rests on. It takes its addresses from the resolve check's facts rather than
35	// resolving again, so a change to how an address is written there would
36	// silently leave this stage with nothing to route to — and the check would go
37	// Unknown on a machine whose routing table is perfectly readable.
38	func TestTheRouteStageReadsWhatTheResolveStageWrote(t *testing.T) {
39		prior := resolvedTo(t, net.ParseIP("93.184.216.34"), net.ParseIP("2606:2800:220:1::1"))
40	
41		got := targetAddresses(target(), &prior)
42		if len(got) != 2 {
43			t.Fatalf("targetAddresses read %d addresses from the resolve check, want 2: %v", len(got), got)
44		}
45		if got[0].String() != "93.184.216.34" || got[1].String() != "2606:2800:220:1::1" {
46			t.Fatalf("addresses = %v, want the two the resolve stage recorded", got)
47		}
48	}
49	
50	// TestALiteralTargetIsItsOwnAddress covers the case where there is no resolve
51	// check to read: the target is already an address.
52	func TestALiteralTargetIsItsOwnAddress(t *testing.T) {
53		var none Results
54		got := targetAddresses(Target{Host: "10.2.3.4", Port: 443}, &none)
55		if len(got) != 1 || got[0].String() != "10.2.3.4" {
56			t.Fatalf("addresses = %v, want [10.2.3.4]", got)
57		}
58	}
59	
60	// TestTheWayOutIsNamedByItsInterface fixes what the summary says. The gateway
61	// is in the facts; the interface is what the user recognises.
62	func TestTheWayOutIsNamedByItsInterface(t *testing.T) {
63		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
64			return RouteHop{
65				Interface: "ProtonVPN",
66				Source:    net.ParseIP("10.2.0.2"),
67			}, nil
68		}}
69	
70		c := routeCheck(t, env, target(), resolvedTo(t, net.ParseIP("93.184.216.34")))
71		if c.Verdict != OK {
72			t.Fatalf("verdict = %v (%s), want OK", c.Verdict, c.Summary)
73		}
74		if !strings.Contains(c.Summary, "ProtonVPN") {
75			t.Fatalf("summary = %q, want the interface named", c.Summary)
76		}
77		if factValue(c, "Source address") != "10.2.0.2" {
78			t.Fatalf("source address fact = %q, want 10.2.0.2", factValue(c, "Source address"))
79		}
80	}
81	
82	// TestADirectlyConnectedTargetSaysSoRatherThanNothing covers the empty gateway.
83	// A blank line where a gateway would be reads as a missing measurement; "no
84	// gateway" is an answer, and it rules out every hop beyond the local segment.
85	func TestADirectlyConnectedTargetSaysSoRatherThanNothing(t *testing.T) {
86		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
87			return RouteHop{Interface: "Ethernet 2", Source: net.ParseIP("192.168.1.21")}, nil
88		}}
89	
90		c := routeCheck(t, env, Target{Host: "192.168.1.1", Port: 443}, Results{})
91		if got := factValue(c, "Gateway"); got != "directly connected" {
92			t.Fatalf("gateway fact = %q, want it to state the absence", got)
93		}
94	}
95	
96	// TestARouteLookupThatFailsIsUnknownAndNeverFail is D20 in this stage. A
97	// lookup that could not answer is not a machine with no route, and reporting
98	// the first as the second is precisely the defect this codebase keeps finding.
99	// "Could not answer" means an error that does not prove the absence: a bare
100	// text error here. An error that nettrace.IsNoRoute recognizes is a proof, and
101	// is covered by TestRouteErrorsAreClassifiedProvenVersusUndetermined.
102	func TestARouteLookupThatFailsIsUnknownAndNeverFail(t *testing.T) {
103		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
104			return RouteHop{}, errors.New("network is unreachable")
105		}}
106	
107		c := routeCheck(t, env, target(), resolvedTo(t, net.ParseIP("93.184.216.34")))
108		if c.Verdict != Unknown {
109			t.Fatalf("verdict = %v (%s), want Unknown", c.Verdict, c.Summary)
110		}
111		if strings.Contains(strings.ToLower(c.Summary), "no route") {
112			t.Fatalf("summary = %q — it must not claim there is no route", c.Summary)
113		}
114	}
115	
116	// TestOneFamilyWithoutARouteWarnsRatherThanHidingIt is the IPv6 case, which is
117	// the one worth reporting: a client that prefers IPv6 hangs before falling
118	// back, and every other check in the run reports the symptom instead.
119	func TestOneFamilyWithoutARouteWarnsRatherThanHidingIt(t *testing.T) {
120		env := fakeEnv{route: func(_ context.Context, ip net.IP) (RouteHop, error) {
121			if ip.To4() == nil {
122				return RouteHop{}, nettrace.ErrNoRoute
123			}
124			return RouteHop{Interface: "Ethernet 2", Source: net.ParseIP("192.168.1.21")}, nil
125		}}
126	
127		prior := resolvedTo(t, net.ParseIP("93.184.216.34"), net.ParseIP("2606:2800:220:1::1"))
128		c := routeCheck(t, env, target(), prior)
129	
130		if c.Verdict != Warn || c.Reason != ReasonPartialRoute {
131			t.Fatalf("verdict = %v/%q, want Warn/partial-route (%s)", c.Verdict, c.Reason, c.Summary)
132		}
133		if !strings.Contains(c.Summary, "1 of 2") {
134			t.Fatalf("summary = %q, want it to count what is missing", c.Summary)
135		}
136		if factValue(c, "No route") == "" {
137			t.Fatalf("the address without a route is not named in the facts")
138		}
139	}
140	
141	// factValues returns every value recorded under key, in order.
142	func factValues(c Check, key string) []string {
143		var out []string
144		for _, f := range c.Facts {
145			if f.Key == key {
146				out = append(out, f.Value)
147			}
148		}
149		return out
150	}
151	
152	// TestRouteErrorsAreClassifiedProvenVersusUndetermined pins DEVDESK-474: the
153	// stage separates an absence of route that the kernel proved
154	// (nettrace.IsNoRoute) from a lookup that merely failed. The first is a
155	// finding; the second stays Unknown (D20). The raw system text, which is in the
156	// machine's language, lives only in fact values, never in the Summary (Rule 129).
157	func TestRouteErrorsAreClassifiedProvenVersusUndetermined(t *testing.T) {
158		const (
159			v4  = "93.184.216.34"
160			v6  = "2606:2800:220:1::1"
161			v4b = "93.184.216.35"
162		)
163		routed := RouteHop{Interface: "Ethernet 2", Source: net.ParseIP("192.168.1.21")}
164		textErr := errors.New("network is unreachable")
165		frErr := errors.New("Réseau inaccessible")
166	
167		tests := []struct {
168			name          string
169			ips           []string
170			errs          map[string]error // per address; absent means routed
171			verdict       Verdict
172			reason        Reason // "" means not asserted
173			wantSummary   []string
174			denySummary   []string
175			wantNoRoute   int
176			wantUndeterm  int
177			noRouteFactIn string // substring expected in a No route fact value
178			undetFactIn   string // substring expected in a Route undetermined fact value
179		}{
180			{
181				name: "all addresses proven by ErrNoRoute", ips: []string{v4, v6},
182				errs:    map[string]error{v4: nettrace.ErrNoRoute, v6: nettrace.ErrNoRoute},
183				verdict: Fail, wantSummary: []string{"no local route"}, wantNoRoute: 2,
184			},
185			{
186				name: "wrapped ENETUNREACH is a proof", ips: []string{v4},
187				errs:    map[string]error{v4: fmt.Errorf("x: %w", syscall.ENETUNREACH)},
188				verdict: Fail, wantSummary: []string{"no local route"}, wantNoRoute: 1,
189			},
190			{
191				name: "wrapped EHOSTUNREACH is a proof", ips: []string{v4},
192				errs:    map[string]error{v4: fmt.Errorf("x: %w", syscall.EHOSTUNREACH)},
193				verdict: Fail, wantSummary: []string{"no local route"}, wantNoRoute: 1,
194			},
195			{
196				name: "text error alone is undetermined", ips: []string{v4},
197				errs:    map[string]error{v4: textErr},
198				verdict: Unknown, wantSummary: []string{"could not be determined"},
199				denySummary: []string{"no route"}, wantUndeterm: 1,
200			},
201			{
202				name: "routed v4 plus proven v6", ips: []string{v4, v6},
203				errs:    map[string]error{v6: nettrace.ErrNoRoute},
204				verdict: Warn, reason: ReasonPartialRoute,
205				wantSummary: []string{"1 of 2 addresses have no local route"}, wantNoRoute: 1,
206			},
207			{
208				name: "routed v4 plus undetermined v6 stays OK", ips: []string{v4, v6},
209				errs:    map[string]error{v6: textErr},
210				verdict: OK, reason: Reason("route-undetermined"),
211				wantSummary: []string{"undetermined for 1 of 2"},
212				denySummary: []string{"no local route"}, wantUndeterm: 1,
213			},
214			{
215				name: "one routed, one proven, one undetermined", ips: []string{v4, v6, v4b},
216				errs:    map[string]error{v6: nettrace.ErrNoRoute, v4b: textErr},
217				verdict: Warn, reason: ReasonPartialRoute,
218				wantSummary: []string{"1 of 3", "no local route", "undetermined"},
219				wantNoRoute: 1, wantUndeterm: 1,
220			},
221			{
222				name: "none routed, one proven, one undetermined", ips: []string{v4, v6},
223				errs:    map[string]error{v4: nettrace.ErrNoRoute, v6: textErr},
224				verdict: Unknown, wantNoRoute: 1, wantUndeterm: 1,
225			},
226			{
227				name: "non-English text stays out of the summary", ips: []string{v4},
228				errs:    map[string]error{v4: frErr},
229				verdict: Unknown, denySummary: []string{"Réseau", "inaccessible"},
230				wantUndeterm: 1, undetFactIn: "Réseau inaccessible",
231			},
232			{
233				name: "non-English text in a proven error stays out of the summary", ips: []string{v4},
234				errs:    map[string]error{v4: fmt.Errorf("%w: %w", nettrace.ErrNoRoute, frErr)},
235				verdict: Fail, denySummary: []string{"Réseau", "inaccessible"},
236				wantNoRoute: 1, noRouteFactIn: "Réseau inaccessible",
237			},
238			{
239				name: "context canceled is undetermined", ips: []string{v4},
240				errs:    map[string]error{v4: context.Canceled},
241				verdict: Unknown, denySummary: []string{"no local route"}, wantUndeterm: 1,
242			},
243		}
244	
245		for _, tc := range tests {
246			t.Run(tc.name, func(t *testing.T) {
247				env := fakeEnv{route: func(_ context.Context, ip net.IP) (RouteHop, error) {
248					if err, bad := tc.errs[ip.String()]; bad {
249						return RouteHop{}, err
250					}
251					return routed, nil
252				}}
253				var ips []net.IP
254				for _, s := range tc.ips {
255					ips = append(ips, net.ParseIP(s))
256				}
257				c := routeCheck(t, env, target(), resolvedTo(t, ips...))
258	
259				if c.Verdict != tc.verdict {
260					t.Fatalf("verdict = %v, want %v (%s)", c.Verdict, tc.verdict, c.Summary)
261				}
262				if tc.reason != "" && c.Reason != tc.reason {
263					t.Fatalf("reason = %q, want %q", c.Reason, tc.reason)
264				}
265				for _, w := range tc.wantSummary {
266					if !strings.Contains(c.Summary, w) {
267						t.Errorf("summary = %q, want it to contain %q", c.Summary, w)
268					}
269				}
270				for _, d := range tc.denySummary {
271					if strings.Contains(strings.ToLower(c.Summary), strings.ToLower(d)) {
272						t.Errorf("summary = %q, must not contain %q", c.Summary, d)
273					}
274				}
275				noRoute, undet := factValues(c, "No route"), factValues(c, "Route undetermined")
276				if len(noRoute) != tc.wantNoRoute {
277					t.Errorf("%d No route facts %v, want %d", len(noRoute), noRoute, tc.wantNoRoute)
278				}
279				if len(undet) != tc.wantUndeterm {
280					t.Errorf("%d Route undetermined facts %v, want %d", len(undet), undet, tc.wantUndeterm)
281				}
282				if tc.noRouteFactIn != "" && !strings.Contains(strings.Join(noRoute, "|"), tc.noRouteFactIn) {
283					t.Errorf("No route facts %v, want the raw text %q", noRoute, tc.noRouteFactIn)
284				}
285				if tc.undetFactIn != "" && !strings.Contains(strings.Join(undet, "|"), tc.undetFactIn) {
286					t.Errorf("Route undetermined facts %v, want the raw text %q", undet, tc.undetFactIn)
287				}
288			})
289		}
290	}
291	
292	// TestTheRouteStageGatesNothing keeps a machine whose routing table cannot be
293	// read from losing every check below it. The reach stage makes the same
294	// promise for the same reason.
295	func TestTheRouteStageGatesNothing(t *testing.T) {
296		for _, s := range stages() {
297			if s.id == StageRoute && s.gate != "" {
298				t.Fatalf("the route stage gates %q — a routing table that cannot be read "+
299					"must not cascade over the port and the certificate", s.gate)
300			}
301		}
302	}
303	
304	// TestOnlyTheFirstAddressesAreRouted bounds the work for a name behind a large
305	// pool. The question is which way out, not how many addresses there are.
306	func TestOnlyTheFirstAddressesAreRouted(t *testing.T) {
307		var many []net.IP
308		for i := 0; i < maxRoutedAddresses+5; i++ {
309			many = append(many, net.IPv4(93, 184, 216, byte(i)))
310		}
311	
312		got := targetAddresses(target(), func() *Results { r := resolvedTo(t, many...); return &r }())
313		if len(got) != maxRoutedAddresses {
314			t.Fatalf("routed %d addresses, want the cap of %d", len(got), maxRoutedAddresses)
315		}
316	}
317	
318	// factValue returns the first value recorded under key, or "".
319	func factValue(c Check, key string) string {
320		for _, f := range c.Facts {
321			if f.Key == key {
322				return f.Value
323			}
324		}
325		return ""
326	}
